class CustomerFilterTest {

    private static final Customer JARNO_MAKINEN = new Customer(
            1009, "Jarno", "Mäkinen", "jarno.makinen.1009@example.com", "Netherlands", CustomerStatus.ACTIVE);
    private static final Customer JOSEPHINE_AALTONEN = new Customer(
            1035, "Joséphine", "Aaltonen", "josefine.aaltonen.1035@example.com", "Portugal", CustomerStatus.CLOSED);

    @Test
    void aBlankNameMatchesEveryone() {
        assertTrue(new CustomerFilter("", Set.of()).asPredicate().test(JARNO_MAKINEN));
        assertTrue(new CustomerFilter("  \t ", Set.of()).asPredicate().test(JARNO_MAKINEN));
    }

    @Test
    void eachTermMayMatchTheFirstOrTheLastName() {
        assertTrue(new CustomerFilter("jarno mäk", Set.of()).asPredicate().test(JARNO_MAKINEN));
        assertTrue(new CustomerFilter("mäk jarno", Set.of()).asPredicate().test(JARNO_MAKINEN));
        assertFalse(new CustomerFilter("jarno aalt", Set.of()).asPredicate().test(JARNO_MAKINEN));
    }

    @Test
    void caseAndAccentsAreIgnoredInBothDirections() {
        assertTrue(new CustomerFilter("makinen", Set.of()).asPredicate().test(JARNO_MAKINEN));
        assertTrue(new CustomerFilter("MAKINEN", Set.of()).asPredicate().test(JARNO_MAKINEN));
        assertTrue(new CustomerFilter("mäkinen", Set.of()).asPredicate().test(JARNO_MAKINEN));
        assertTrue(new CustomerFilter("josephine", Set.of()).asPredicate().test(JOSEPHINE_AALTONEN));
        assertTrue(new CustomerFilter("JOSÉPHINE", Set.of()).asPredicate().test(JOSEPHINE_AALTONEN));
    }

    @Test
    void statusesRestrictMatchesWhenAnyAreSelected() {
        assertTrue(new CustomerFilter("", Set.of(CustomerStatus.ACTIVE)).asPredicate().test(JARNO_MAKINEN));
        assertFalse(new CustomerFilter("", Set.of(CustomerStatus.CLOSED)).asPredicate().test(JARNO_MAKINEN));
        assertTrue(new CustomerFilter("", Set.of(CustomerStatus.PENDING, CustomerStatus.CLOSED))
                .asPredicate().test(JOSEPHINE_AALTONEN));
    }
}
