+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * Which customers a query returns: a name search and a set of statuses.
+ *
+ * <p>A customer matches when it satisfies both parts.
+ *
+ * @param name     text to search the first and last names for. It is split on
+ *                 whitespace into terms, and every term must appear in the first
+ *                 name or the last name. Blank means no name filter.
+ * @param statuses statuses to keep; empty means every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = Set.copyOf(statuses);
+    }
+
+    /**
+     * Returns a predicate that tests one customer against this filter.
+     *
+     * <p>The search terms are folded once, when the predicate is built, rather
+     * than once per customer.
+     */
+    public Predicate<Customer> asPredicate() {
+        List<String> terms = WHITESPACE.splitAsStream(name)
+                .filter(term -> !term.isEmpty())
+                .map(CustomerFilter::fold)
+                .toList();
+        Set<CustomerStatus> allowed = statuses;
+        return customer -> (allowed.isEmpty() || allowed.contains(customer.status()))
+                && nameMatches(terms, customer);
+    }
+
+    private static boolean nameMatches(List<String> terms, Customer customer) {
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    /**
+     * Folds text for comparison: accents are removed and case is ignored, so
+     * {@code Mäkinen}, {@code MAKINEN} and {@code makinen} all fold to the same text.
+     */
+    private static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
