+    private static Set<CustomerStatus> statusesFrom(QueryParameters parameters) {
+        Set<String> names = parameters.getParameters(STATUS_PARAMETER).stream()
+                .flatMap(value -> Arrays.stream(value.split(",")))
+                .map(String::strip)
+                .collect(Collectors.toSet());
+        return Arrays.stream(CustomerStatus.values())
+                .filter(status -> names.contains(status.name()))
+                .collect(Collectors.toSet());
+    }
+
+    private Stream<Customer> fetchPage(Query<Customer, CustomerFilter> query) {
+        return customerService
+                .list(query.getOffset(), query.getLimit(), toSorts(query.getSortOrders()), filterOf(query))
+                .stream();
+    }
+
+    /**
+     * Counts the customers matching the filter. The grid asks for this count
+     * whenever its rows change, so the summary takes the number from here rather
+     * than running a second count query of its own.
+     */
+    private int countMatching(Query<Customer, CustomerFilter> query) {
+        int matching = customerService.count(filterOf(query));
+        matchingCustomers.set(matching);
+        return matching;
+    }
+
+    private static CustomerFilter filterOf(Query<Customer, CustomerFilter> query) {
+        return query.getFilter().orElse(CustomerFilter.NONE);
