+        assertThat(summary()).hasText("Showing 12 of 500");
+        GridElement.get(page).assertRowCount(12);
+        assertThat(page).hasURL(Pattern.compile(".*/\\?name=josephine"));
+        assertEquals(1, queryLog.countQueries().size(), "one count query for the whole word");
+        assertEquals(1, queryLog.pageQueries().size(), "one page query for the whole word");
+        assertEquals(historyLength, historyLength(), "typing must not add history entries");
+
+        nameFilter().fill("");
+        assertThat(summary()).hasText("Showing 500 of 500");
+        assertThat(page).hasURL(Pattern.compile("http://localhost:\\d+/"));
+    }
