+        page.navigate("http://localhost:" + port + "/?name=vir&status=CLOSED,ACTIVE");
+
+        assertThat(nameFilter()).hasValue("vir");
+        assertThat(summary()).hasText("Showing 10 of 500");
+        GridElement.get(page).assertRowCount(10);
+    }
+
+    @Test
+    void choosingStatusesWritesThemToTheAddressBarInDeclarationOrder() {
+        assertThat(summary()).hasText("Showing 500 of 500");
+
+        statusFilter().click();
+        page.locator("vaadin-multi-select-combo-box-item").filter(new Locator.FilterOptions().setHasText("CLOSED")).click();
+        page.locator("vaadin-multi-select-combo-box-item").filter(new Locator.FilterOptions().setHasText("ACTIVE")).click();
+        page.keyboard().press("Escape");
+
+        assertThat(summary()).hasText("Showing 333 of 500");
+        // Vaadin percent-encodes the comma; it decodes to the same ACTIVE,CLOSED.
+        assertThat(page).hasURL(Pattern.compile(".*/\\?status=ACTIVE(,|%2C)CLOSED"));
+
+        statusFilter().click();
+        page.locator("vaadin-multi-select-combo-box-item").filter(new Locator.FilterOptions().setHasText("ACTIVE")).click();
+        page.locator("vaadin-multi-select-combo-box-item").filter(new Locator.FilterOptions().setHasText("CLOSED")).click();
+        page.keyboard().press("Escape");
+
+        assertThat(summary()).hasText("Showing 500 of 500");
+        assertThat(page).hasURL(Pattern.compile("http://localhost:\\d+/"));
+    }
+
+    @Test
+    void sortingIsDoneByTheBackendWhileFiltered() {
+        page.navigate("http://localhost:" + port + "/?name=makinen");
+        GridElement grid = GridElement.get(page);
+        grid.assertRowCount(15);
+
+        page.locator("vaadin-grid-sorter").filter(new Locator.FilterOptions().setHasText("First name")).first().click();
+
+        assertThat(grid.findCell(0, 0).orElseThrow().getCellContentLocator()).hasText("Dagny");
+        assertThat(summary()).hasText("Showing 15 of 500");
+    }
+
+    private Locator nameFilter() {
+        return page.locator("input[placeholder='Filter by name']");
+    }
+
+    private Locator statusFilter() {
+        return page.locator("vaadin-multi-select-combo-box input").first();
+    }
+
+    private Locator summary() {
+        return page.locator("span").filter(new Locator.FilterOptions().setHasText("Showing ")).first();
+    }
+
+    private long historyLength() {
+        return ((Number) page.evaluate("() => window.history.length")).longValue();
+    }
+}
